async function save(g){if(!pool)return;await pool.query(`INSERT INTO games(code,state,updated_at) VALUES($1,$2,NOW()) ON CONFLICT(code) DO UPDATE SET state=$2,updated_at=NOW()`,[g.code,JSON.stringify({...g,host:null,displays:[],teams:g.teams.map(t=>({...t,players:[]}))})]).catch(console.error)}
async function init(){if(!pool)return;await pool.query(`CREATE TABLE IF NOT EXISTS games(code TEXT PRIMARY KEY,state JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);const rs=await pool.query(`SELECT code,state FROM games WHERE updated_at>NOW()-INTERVAL '24 hours'`);for(const r of rs.rows){const g=r.state;g.code=r.code;g.host=null;g.displays=new Set();g.teams.forEach(t=>t.players=[]);g.questionBank=ensureBank(g.questionBank||defaultQuestions());g.teams.forEach(t=>{t.doubleUsed=!!t.doubleUsed;t.doubleActive=!!t.doubleActive;t.doublePlayer=t.doublePlayer||'';});games.set(g.code,g)}}
function emit(g){
  const room=io.sockets.adapter.rooms.get(g.code)||new Set();
  for(const sid of room){
    const sock=io.sockets.sockets.get(sid);
    if(sock) sock.emit('state',pub(g,sock.data?.role));
  }
  save(g);
}function get(c){return games.get(clean(c))}
