 s.on('host:saveBank',({code,bank}={})=>{const g=get(code);if(!g||g.host!==s.id)return;const cleanBank=sanitizeBank(bank);if(!cleanBank.length)return s.emit('error:msg','يجب أن تحتوي قاعدة الأسئلة على سؤال وإجابة واحدة على الأقل');g.questionBank=ensureBank(cleanBank);emit(g);s.emit('bank:saved');});
